        p.processBlock(audio,midi);const auto high=meter.processSamplesUp(juce::dsp::AudioBlock<const float>(audio));for(size_t c=0;c<high.getNumChannels();++c)for(size_t n=0;n<high.getNumSamples();++n)truePeak=std::max(truePeak,double(std::abs(high.getSample(int(c),int(n)))));rawPeak=std::max(rawPeak,double(p.takeOutputPeak()));
        double blockEnergy=0;for(int n=0;n<512;++n){const float l=audio.getSample(0,n),r=audio.getSample(1,n);if(!std::isfinite(l)||!std::isfinite(r))throw std::runtime_error("Non-finite audio");peak=std::max(peak,double(std::max(std::abs(l),std::abs(r))));const double e=(l*l+r*r)*.5;energy+=e;blockEnergy+=e;++frames;
            if(detailed){spectrum[size_t(fill++)]=l; if(fill==2048){for(int i=0;i<2048;++i)spectrum[size_t(i)]*=.5f-.5f*std::cos(2*juce::MathConstants<float>::pi*i/2047);fft.performFrequencyOnlyForwardTransform(spectrum.data());for(int i=1;i<1024;++i){const double hz=i*48000.0/2048;const int band=juce::jlimit(0,count-1,int(std::log(hz/20)/std::log(16000.0/20)*count));const double e=spectrum[size_t(i)]*spectrum[size_t(i)];bands[size_t(band)]+=e;if(b<20)attack[size_t(band)]+=e;}spectrum.fill(0);fill=0;}}
        }
